import javax.tools.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.net.*;import java.util.*;
/** Real native-control helper with controllable Camera2 characteristics/request builders. */
public final class NativeControlsRegression {
 static void write(Path root,List<String> files,String name,String source)throws Exception{Path f=root.resolve(name);Files.createDirectories(f.getParent());Files.write(f,source.getBytes(StandardCharsets.UTF_8));files.add(f.toString());}
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]),dir=root.resolve("build/native-control-tests"),classes=dir.resolve("classes");Files.createDirectories(classes);List<String> files=new ArrayList<>();
  write(dir,files,"android/util/Range.java","package android.util;public class Range<T>{T a,b;public Range(T x,T y){a=x;b=y;}public T getLower(){return a;}public T getUpper(){return b;}}");
  write(dir,files,"android/hardware/camera2/CaptureRequest.java",request());
  write(dir,files,"android/hardware/camera2/CameraCharacteristics.java",characteristics());
  write(dir,files,"com/silverroom/camera/NativeControlProbe.java",probe());
  for(String n:new String[]{"NativeCameraControls","PhotoCapabilities","PhotoControls","LogicalZoomState","LensPlan"})files.add(root.resolve("src/com/silverroom/camera/"+n+".java").toString());
  List<String> opts=new ArrayList<>(Arrays.asList("--release","8","-encoding","UTF-8","-d",classes.toString()));opts.addAll(files);if(ToolProvider.getSystemJavaCompiler().run(null,null,null,opts.toArray(new String[0]))!=0)throw new AssertionError("Native control fixture compilation");
  try(URLClassLoader loader=new URLClassLoader(new URL[]{classes.toUri().toURL()},null)){try{for(Object n:(List<?>)loader.loadClass("com.silverroom.camera.NativeControlProbe").getMethod("run").invoke(null))System.out.println("PASS "+n);}catch(java.lang.reflect.InvocationTargetException e){throw new AssertionError("Native control request regression",e.getCause());}}
 }
 static String request(){return "package android.hardware.camera2;import java.util.*;public class CaptureRequest{public static class Key<T>{}"+
 "public static final int CONTROL_AE_MODE_OFF=0,CONTROL_AWB_MODE_OFF=0,CONTROL_AWB_MODE_AUTO=1,FLASH_MODE_OFF=0;"+
 "public static final Key<Integer> CONTROL_AE_MODE=new Key<>(),SENSOR_SENSITIVITY=new Key<>(),CONTROL_AWB_MODE=new Key<>(),CONTROL_AE_EXPOSURE_COMPENSATION=new Key<>(),FLASH_MODE=new Key<>();public static final Key<Long> SENSOR_EXPOSURE_TIME=new Key<>(),SENSOR_FRAME_DURATION=new Key<>();public static final Key<Float> LENS_APERTURE=new Key<>();public static final Key<Boolean> CONTROL_AE_LOCK=new Key<>();"+
 "public static class Builder{public Map<Key<?>,Object> values=new HashMap<>();public Map<String,Map<Key<?>,Object>> physical=new HashMap<>();public <T> void set(Key<T> k,T v){values.put(k,v);}public <T>void setPhysicalCameraKey(Key<T> k,T v,String id){physical.computeIfAbsent(id,n->new HashMap<>()).put(k,v);}}}";}
 static String characteristics(){return "package android.hardware.camera2;import java.util.*;import android.util.Range;public class CameraCharacteristics{public static class Key<T>{}public static final int REQUEST_AVAILABLE_CAPABILITIES_MANUAL_SENSOR=1;public static final Key<int[]> REQUEST_AVAILABLE_CAPABILITIES=new Key<>(),CONTROL_AE_AVAILABLE_MODES=new Key<>(),CONTROL_AWB_AVAILABLE_MODES=new Key<>();public static final Key<float[]> LENS_INFO_AVAILABLE_APERTURES=new Key<>();public static final Key<Range<Integer>> SENSOR_INFO_SENSITIVITY_RANGE=new Key<>();public static final Key<Range<Long>> SENSOR_INFO_EXPOSURE_TIME_RANGE=new Key<>();public static final Key<Long> SENSOR_INFO_MAX_FRAME_DURATION=new Key<>();public Map<Key<?>,Object> values=new HashMap<>();public List<CaptureRequest.Key<?>> keys=new ArrayList<>(),physical=new ArrayList<>();@SuppressWarnings(\"unchecked\")public <T>T get(Key<T> k){return (T)values.get(k);}public <T> void set(Key<T> k,T v){values.put(k,v);}public List<CaptureRequest.Key<?>> getAvailableCaptureRequestKeys(){return keys;}public List<CaptureRequest.Key<?>> getAvailablePhysicalCameraRequestKeys(){return physical;}}";}
 static String probe(){return "package com.silverroom.camera;import android.hardware.camera2.*;import android.util.Range;import java.util.*;public class NativeControlProbe{static List<String> passed=new ArrayList<>();static void check(boolean v,String n){if(!v)throw new AssertionError(n);passed.add(n);}static CameraCharacteristics caps(){CameraCharacteristics c=new CameraCharacteristics();c.set(CameraCharacteristics.REQUEST_AVAILABLE_CAPABILITIES,new int[]{1});c.set(CameraCharacteristics.CONTROL_AE_AVAILABLE_MODES,new int[]{0,1});c.set(CameraCharacteristics.CONTROL_AWB_AVAILABLE_MODES,new int[]{0,1,2,5});c.set(CameraCharacteristics.SENSOR_INFO_SENSITIVITY_RANGE,new Range<Integer>(50,6400));c.set(CameraCharacteristics.SENSOR_INFO_EXPOSURE_TIME_RANGE,new Range<Long>(10000L,3000000000L));c.set(CameraCharacteristics.SENSOR_INFO_MAX_FRAME_DURATION,4000000000L);c.set(CameraCharacteristics.LENS_INFO_AVAILABLE_APERTURES,new float[]{1.75f,2.8f});c.keys.addAll(Arrays.asList(CaptureRequest.CONTROL_AE_MODE,CaptureRequest.SENSOR_SENSITIVITY,CaptureRequest.SENSOR_EXPOSURE_TIME,CaptureRequest.CONTROL_AWB_MODE,CaptureRequest.CONTROL_AE_LOCK,CaptureRequest.CONTROL_AE_EXPOSURE_COMPENSATION,CaptureRequest.FLASH_MODE,CaptureRequest.SENSOR_FRAME_DURATION,CaptureRequest.LENS_APERTURE));c.physical.addAll(c.keys);return c;}public static List<String> run(){"+
 "CameraCharacteristics owner=caps(),sensor=caps();sensor.set(CameraCharacteristics.SENSOR_INFO_SENSITIVITY_RANGE,new Range<Integer>(100,1600));sensor.set(CameraCharacteristics.SENSOR_INFO_EXPOSURE_TIME_RANGE,new Range<Long>(20000L,1000000000L));sensor.set(CameraCharacteristics.CONTROL_AWB_AVAILABLE_MODES,new int[]{0,1,5});PhotoCapabilities cap=NativeCameraControls.capabilities(owner,sensor,null);check(cap.manual&&cap.isoMin==100&&cap.isoMax==1600&&cap.timeMin==20000&&cap.timeMax==1000000000L,\"Production native capability snapshot intersects logical and optical sensor ISO/time limits\");check(Arrays.equals(cap.whites,new int[]{1,5}),\"Only mutually supported native white balance presets are exposed; manual color gains are not invented\");"+
 "for(String id:new String[]{null,\"3\",\"4\"}){cap=NativeCameraControls.capabilities(owner,sensor,id);CaptureRequest.Builder b=new CaptureRequest.Builder();PhotoControls p=new PhotoControls(true,800,500000000L,5,2.8f);NativeCameraControls.apply(b,p,cap,id);Map<CaptureRequest.Key<?>,Object> m=id==null?b.values:b.physical.get(id);check(m.get(CaptureRequest.CONTROL_AE_MODE).equals(0)&&m.get(CaptureRequest.SENSOR_SENSITIVITY).equals(800)&&m.get(CaptureRequest.SENSOR_EXPOSURE_TIME).equals(500000000L)&&m.get(CaptureRequest.SENSOR_FRAME_DURATION).equals(500000000L),\"Native manual ISO/shutter/frame duration apply to route \"+id);check(m.get(CaptureRequest.CONTROL_AE_LOCK).equals(false)&&m.get(CaptureRequest.FLASH_MODE).equals(0)&&m.get(CaptureRequest.CONTROL_AE_EXPOSURE_COMPENSATION).equals(0),\"Manual route \"+id+\" disables AE lock, phone flash and automatic compensation\");NativeCameraControls.apply(b,PhotoControls.automatic(),cap,id);check(m.get(CaptureRequest.CONTROL_AWB_MODE).equals(1),\"Returning to automatic white balance replaces the prior preset on route \"+id);}"+
 "owner.physical.remove(CaptureRequest.SENSOR_SENSITIVITY);check(!NativeCameraControls.capabilities(owner,sensor,\"4\").manual&&NativeCameraControls.capabilities(owner,sensor,null).manual,\"Missing physical manual request key disables only the bound path\");owner=caps();owner.keys.remove(CaptureRequest.CONTROL_AWB_MODE);cap=NativeCameraControls.capabilities(owner,sensor,null);CaptureRequest.Builder b=new CaptureRequest.Builder();NativeCameraControls.apply(b,PhotoControls.automatic(),cap,null);check(cap.whites.length==0&&!b.values.containsKey(CaptureRequest.CONTROL_AWB_MODE),\"Unsupported WB request key is neither presented nor submitted\");"+
 "owner=caps();owner.keys.remove(CaptureRequest.LENS_APERTURE);cap=NativeCameraControls.capabilities(owner,sensor,null);b=new CaptureRequest.Builder();NativeCameraControls.apply(b,new PhotoControls(false,100,10000000L,1,2.8f),cap,null);check(cap.apertures.length==1&&!b.values.containsKey(CaptureRequest.LENS_APERTURE),\"Read-only aperture does not create a fake adjustable aperture\");owner=caps();sensor.set(CameraCharacteristics.REQUEST_AVAILABLE_CAPABILITIES,new int[]{});check(!NativeCameraControls.capabilities(owner,sensor,null).manual,\"A manual-capable owner cannot grant unsupported optical-sensor manual controls\");"+
 "LogicalZoomState state=new LogicalZoomState();Object tag=state.tag(4,8,12);check(LogicalZoomState.meter(tag)==4&&LogicalZoomState.regions(tag)==8&&LogicalZoomState.controls(tag)==12,\"Request tags independently preserve lock, region and native-control epochs\");check(LogicalZoomState.controls(state.tag(4,8,13))!=LogicalZoomState.controls(tag),\"Old native-control results cannot match the next parameter snapshot\");return passed;}}";}
}
